def rule_page1_identification_keywords_any_label(doc: dict) -> list[dict]:
    """Match any page-1 span with identification keywords like incorporation, organization, or employer identification."""
    try:
        import re
        out = []
        for span in doc.get("texts", []):
            if span.get("page_no") != 1:
                continue
            txt = ((span.get("text") or "") + " " + (span.get("text_span") or "")).lower()
            if "jurisdiction of incorporation" in txt or "employer identification" in txt or "incorporation or organization" in txt:
                out.append(span)
        return out
    except Exception:
        return []

def rule_page1_company_block_all_values(doc: dict) -> list[dict]:
    """Match all page-1 spans in the company identification block containing state, file number, EIN, address labels."""
    try:
        import re
        out = []
        started = False
        for span in doc.get("texts", []):
            if span.get("page_no") != 1:
                continue
            txt = (span.get("text") or "") + " " + (span.get("text_span") or "")
            if not started and re.search(r"exact name of registrant", txt, re.I):
                started = True
            if started:
                if re.search(r"state\s+or\s+other\s+jurisdiction\s+of\s+incorporation", txt, re.I):
                    out.append(span)
                elif re.search(r"commission file", txt, re.I):
                    out.append(span)
                elif re.search(r"employer\s+identification", txt, re.I):
                    out.append(span)
                elif re.fullmatch(r"\d{2}-\d{7}", (span.get("text") or "").strip()):
                    out.append(span)
                elif re.fullmatch(r"(Delaware|New York|New Jersey|Washington|California|Minnesota|Jersey)", (span.get("text") or "").strip(), re.I):
                    out.append(span)
        return out
    except Exception:
        return []

def rule_company_header_siblings_first_20(doc: dict) -> list[dict]:
    """Match early page-1 spans near the company header where state and EIN usually appear."""
    try:
        import re
        texts = doc.get("texts", [])
        out = []
        company_idx = None
        for i, span in enumerate(texts):
            if span.get("page_no") != 1:
                continue
            txt = (span.get("text") or "").strip()
            if span.get("label") == "section_header" and txt:
                if any(k in txt.lower() for k in ["inc.", "incorporated", "plc", "corporation", "company"]):
                    company_idx = i
                    break
        if company_idx is None:
            return []
        for span in texts[company_idx:company_idx + 20]:
            if span.get("page_no") != 1:
                continue
            txt = (span.get("text") or "") + " " + (span.get("text_span") or "")
            if re.search(r"state\s+or\s+other\s+jurisdiction\s+of\s+incorporation", txt, re.I):
                out.append(span)
            elif re.search(r"(i\.?r\.?s\.?\s+)?employer\s+identification", txt, re.I):
                out.append(span)
            elif re.fullmatch(r"\d{2}-\d{7}", (span.get("text") or "").strip()):
                out.append(span)
        return out
    except Exception:
        return []

